{
  "title": "AERO9500 Final Report (Part 2): Space Mission Design",
  "overview": "Develop a preliminary space-mission design that benefits Australia and report the mission concept and its space-segment elements. Use mission-design software of your choice, supported by hand calculations if useful, and justify the proposed design.",
  "deliverables": [
    "One technical-report PDF presenting the mission design and related work.",
    "Relevant design-software screenshots and all relevant STK or PIGI files, included with the report or in an appendix.",
    "If using software other than STK or PIGI, discuss it with the course contact before starting."
  ],
  "format": {
    "length": "Maximum 20 pages for the core report; title page, table of contents, references and other non-core material are excluded.",
    "structure": "Executive summary; Introduction (mission overview and rationale); Main body (mission space segment, including relevant launch, orbit, ground stations, coverage, operations and end-of-life sections); Conclusion; Bibliography.",
    "other": "Use clear, effective engineering-report writing with correct grammar and spelling. Label figures and tables correctly with numbers, titles and references where needed. Cite and reference all material not originating with you; Wikipedia is not an acceptable source."
  },
  "requirements": [
    {
      "id": "R1",
      "text": "Propose a simple mission that benefits Australia and explain its primary mission, overview and rationale."
    },
    {
      "id": "R2",
      "text": "Specify whether the mission uses one or multiple spacecraft."
    },
    {
      "id": "R3",
      "text": "Identify the mission's users, including operator and customers."
    },
    {
      "id": "R4",
      "text": "State the launch site and launch vehicle."
    },
    {
      "id": "R5",
      "text": "Describe the orbit, including its type, characteristics and orbital elements."
    },
    {
      "id": "R6",
      "text": "State whether orbital manoeuvres are required and describe them as relevant."
    },
    {
      "id": "R7",
      "text": "Identify ground-control facilities and explain how often the spacecraft can communicate with ground control."
    },
    {
      "id": "R8",
      "text": "Specify mission duration and end-of-life plans."
    },
    {
      "id": "R9",
      "text": "Use mission-design software; hand calculations may be added where useful. PIGI users must register for its competition to obtain a software licence."
    },
    {
      "id": "R10",
      "text": "Support the mission design with relevant screenshots and provide all relevant STK or PIGI files."
    },
    {
      "id": "R11",
      "text": "Ensure the report has a clear, logical structure and is concise; properly identify and cite all borrowed text, diagrams, ideas and other information."
    }
  ]
}
